body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-1z0xch3 {
				display: flex;
				gap: 28px;
				padding: 32px 24px;
				background: #f3f1ea;
			}
			.card.mk-1z0xch3 {
				width: 120px;
				height: 90px;
				overflow: hidden;
				background: #ffffff;
				font-size: 17px;
				color: #2b2620;
			}
			.pressed.mk-1z0xch3 {
				border: 1px solid #c9c1b0;
				border-radius: 14px;
				transform: scale(0.97);
				outline: 3px solid #1f6feb;
				outline-offset: 2px;
			}
			.lifted.mk-1z0xch3 {
				position: relative;
				outline: 4px solid #d1495b;
				outline-offset: 3px;
			}
			.photo.mk-1z0xch3 {
				width: 180px;
				height: 50px;
				background: #e9a23b;
			}
